#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""MyDesk v299 適用（見積依頼ポータル：業者ごと専用リンク・回答取得）
使い方: dashboard.jsx と同じフォルダで  python3 apply_v299_dashboard.py"""
import gzip, base64, json, sys, os
PATH="dashboard.jsx"
if not os.path.exists(PATH):
    print("❌ dashboard.jsx が見つかりません。同じフォルダで実行してください。"); sys.exit(1)
PAIRS=json.loads('[["H4sIAHeaamoC/0vOzysuUfCNdHEN9o53CvX0cVGwVVAyMjAy0zUw1zUy0i0zsrTQLSzNL0nVLS7JL0ot1i1LzUvJL9JNy8wpSS1SslbQ11d43Dz5cfPqx82dL9bOeNqx9OnaCQAJ40zLWAAAAA==", "H4sIAHeaamoC/0vOzysuUfCNdHEN9o53CvX0cVGwVVAyMjAy0zUw1zUy1i0zsrTULSzNL0nVLcgvKknM0c3JzMtWslbQ11d43Dz5cfPqx82dL9bOeNqx9OnaCQCaKPtiTwAAAA=="], ["H4sIAHeaamoC/0vOzysuUXAJDQ5x9PGOD470c44PDfJRsFVQyigpKSi20tc3Nis3T6swqizPMy8xKUpMTy9KKk81M83MyTRIS0nJK9LLScxNSknULS3K0Uss0M3LLyrJSE0sLtE11MvP00ssL1ayBgA5/d4hZQAAAA==", ""], ["H4sIAHeaamoC/1NQSM7PKy5RiM7MLXAqLa7UUShOLfGEsGMVbBWCUhOTS/RKi1ODSxJLUjXSEnOKUzWtAZMAwvg2AAAA", "H4sIAHeaamoC/1NQSM7PKy5RiM7MLXAqLa7UUShOLfGEsGMVbBWCUhOTS/RKi1ODSxJLUjXSEnOKUzWtuRRg2gryi0oSc+A6A+BcLJqVlDStAfZxTWRwAAAA"], ["H4sIAHeaamoC/1NQSM7PKy5RSExJSU3xTClWsFXISy1XCE4t0dAo0CtLzUvJLyquqYmO1dTLTSzQqLC1Cy4pysxL16iASnqmaGpqWgMAhwb2REcAAAA=", ""], ["", ""]]')
def dec(b): return gzip.decompress(base64.b64decode(b)).decode("utf-8")
raw=open(PATH,"rb").read(); had_crlf=b"\r\n" in raw
text=raw.replace(b"\r\n",b"\n").decode("utf-8")
applied=skipped=0
for eo,en in PAIRS:
    old,new=dec(eo),dec(en)
    if text.count(new)>=1: skipped+=1; continue
    c=text.count(old)
    if c==0:
        print("❌ 対象が見つかりません（現在のビルドを確認してください）:")
        print("   "+old[:80].replace("\n"," / ")); print("   grep MYDESK_BUILD dashboard.jsx"); sys.exit(1)
    if c!=1:
        print("❌ 対象が%d箇所（1箇所想定）: %s"%(c,old[:60].replace("\n"," / "))); sys.exit(1)
    text=text.replace(old,new,1); applied+=1
out=text.replace("\n","\r\n").encode("utf-8") if had_crlf else text.encode("utf-8")
open(PATH,"wb").write(out)
print("✅ v299 適用完了 (適用 %d / スキップ %d)"%(applied,skipped))
print("   ビルド: 2026-07-23-v299-quote-portal-link")
